process.on('unhandledRejection', (err) => {
  console.log('!!! UNHANDLED REJECTION:', err.code, err.message)
  process.exit(7)
})

async function main (mode) {
  const fastify = Fastify()

  if (mode === 'async-onsend') {
    fastify.addHook('onSend', async (req, reply, payload) => payload)
  } else if (mode === 'sync-onsend') {
    fastify.addHook('onSend', (req, reply, payload, done) => { done(null, payload) })
  } else if (mode === 'async-preser') {
    fastify.addHook('preSerialization', async (req, reply, payload) => payload)
  }

  fastify.get('/', async (req, reply) => {
    reply.header('x-bad', 'bad\nvalue')
    return { hello: 'world' }
  })

  const res = await fastify.inject({ method: 'GET', url: '/' })
  console.log(mode, '->', res.statusCode, res.payload.slice(0, 120))
}

main(process.argv[2]).catch(e => console.log('caught at top:', e.code, e.message))

