test('invalid response headers with an async onSend hook', async t => {
  const fastify = Fastify()

  fastify.addHook('onSend', async (request, reply, payload) => payload)

  fastify.route({
    method: 'GET',
    url: '/bad-headers',
    handler: (req, reply) => {
      reply.header('smile', '😄')
      reply.send({})
    }
  })

  const fastifyServer = await fastify.listen({ port: 0 })
  t.after(() => fastify.close())

  const { response, body } = await doGet(`${fastifyServer}/bad-headers`)
  t.assert.strictEqual(response.status, 500)
  t.assert.deepStrictEqual(body, {
    statusCode: 500,
    code: 'ERR_INVALID_CHAR',
    error: 'Internal Server Error',
    message: 'Invalid character in header content ["smile"]'
  })
})

