test('an async onSend hook error is handled by the error handler', async t => {
  const fastify = Fastify()

  let invalidateHeaders = true
  fastify.addHook('onSend', async (request, reply, payload) => {
    if (invalidateHeaders) {
      // only the first response gets the invalid header, so that the
      // error handler can send a valid one
      invalidateHeaders = false
      reply.header('smile', '😄')
    }
    return payload
  })

  fastify.route({
    method: 'GET',
    url: '/bad-headers',
    handler: async () => ({ hello: 'world' })
  })

  fastify.setErrorHandler(function (error, request, reply) {
    t.assert.strictEqual(error.code, 'ERR_INVALID_CHAR')
    reply.status(500).send({ ops: true })
  })

  const fastifyServer = await fastify.listen({ port: 0 })
  t.after(() => fastify.close())

  const { response, body } = await doGet(`${fastifyServer}/bad-headers`)
  t.assert.strictEqual(response.status, 500)
  t.assert.deepStrictEqual(body, { ops: true })
})

